import base64,hashlib,json,struct,zlib
from pathlib import Path
from collections import Counter
ROOT=Path.cwd()
REPORT='coordinacion/respuestas/AXIAL-NATIVE-SIGNED512-001-CODEX.json'
r=json.loads((ROOT/REPORT).read_bytes())
def need(b,m):
    if not b:raise AssertionError(m)
def digest(b):return hashlib.sha256(b).hexdigest()
def canon(p):return json.dumps(p,sort_keys=True,separators=(',',':'),allow_nan=False).encode()
def unpack_run(run):
    raw=zlib.decompress(base64.b64decode(run['stdout_zlib_base64'],validate=True))
    need(len(raw)==run['stdout_bytes'] and digest(raw)==run['stdout_sha256'],'raw receipt')
    return json.loads(raw)
for p,h in r['code_doc_sha256'].items():need(digest((ROOT/p).read_bytes())==h,'pin '+p)
L=2**511
def integer(w):
    if type(w) is not list or len(w)!=16 or any(type(x) is not int or not 0<=x<2**32 for x in w):raise ValueError('wordshape')
    u=sum(x<<(32*i) for i,x in enumerate(w))
    return u-2**512 if u>=L else u
def decode(w):
    if type(w) is not int or not 0<=w<2**32:raise ValueError('scalarshape')
    exponent=(w>>23)&255;mantissa=w&0x7fffff
    if exponent==255 or (exponent==0 and mantissa):raise ValueError('normalorzero')
    return 0 if exponent==0 else ((mantissa+2**23)*2**(exponent-1))*(-1 if w>>31 else 1)
def hilo(w):return decode(w[0])+decode(w[1])
all_counts={};unverifiable_initial_shape_rejections=0
for label,run in [('initial_preserved_FAIL',r['initial_failed_test_run']),('final_PASS',r['test_run'])]:
    body=unpack_run(run)
    need((run['rc']==0)==body['PASS'],'rc consistency')
    need(body['tests']==(8 if label.startswith('initial') else 9),'testcount')
    need(not body['GLSL_compiled'] and not body['GPU_executed'] and not body['accepted_complete_geometry'],'no promotion')
    counts=Counter();rejects=Counter()
    for entry in body['all_own_limb_calls_including_controls']:
        op,args=entry['op'],entry['inputs'];counts[op]+=1
        if label.startswith('initial') and entry['rejected'] and entry['reason']=='16 uint32 limbs' and args==[[0]*16,[0]*16]:
            # Initial JSON erased tuple-vs-list type. Preserve this evidence gap.
            unverifiable_initial_shape_rejections+=1;rejects[op]+=1;continue
        try:
            if not label.startswith('initial'):
                need(len(entry['input_container_types'])==len(args),'type receipt')
                if op!='decode32_scaled' and entry['input_container_types']!=['list','list']:raise ValueError('container type')
            if op=='decode32_scaled':out=decode(args[0])
            else:
                a,b=map(integer,args)
                if op=='add':out=a+b
                elif op=='sub':out=a-b
                elif op=='mul':out=a*b
                elif op=='compare':out=(a>b)-(a<b)
                else:raise AssertionError('unknownop')
                if op!='compare' and not -L<=out<L:raise ValueError('overflow')
        except ValueError:
            need(entry['rejected'] and type(entry['reason']) is str,'expected rejection')
            rejects[op]+=1
        else:
            need(not entry['rejected'],'unexpected rejection')
            observed=entry['output'] if op=='compare' else integer(entry['output'])
            need(observed==out,'limb arithmetic oracle')
    all_counts[label]={'calls':dict(counts),'rejects':dict(rejects),'total':sum(counts.values())}
need(unverifiable_initial_shape_rejections==1,'initial serialization evidence gap count')
current=unpack_run(r['test_run'])
need(current['pins']==r['inherited_pins'],'retained pins exactly')
ingress=unpack_run(json.loads((ROOT/'coordinacion/respuestas/AXIAL-NATIVE-INGRESS-001-CODEX.json').read_bytes())['test_run'])['packets']
oldgeo=unpack_run(json.loads((ROOT/'coordinacion/respuestas/AXIAL-GEOMETRY-WORDS-001-CODEX.json').read_bytes())['test_run'])['cases']
need(set(current['cases'])==set(ingress) and len(ingress)==13,'case coverage')
sources=matches=plane_pass=0;matched_cases=set()
for name,packet in ingress.items():
    case=current['cases'][name]
    need(case['input_packet_sha256']==digest(canon(packet)) and packet['manifest']['case_name']==name,'packetpin')
    buffers={k:base64.b64decode(v,validate=True) for k,v in packet['buffers_base64'].items()}
    for k,raw in buffers.items():need(packet['manifest']['buffers'][k]=={'bytes':len(raw),'sha256':digest(raw)},'buffer receipt')
    meta=json.loads(buffers['input_metadata_json'])
    need(meta['object_ids']==['M','D'] and meta['kinds']==['mirror','det'],'M-D profile')
    need(case['source_order']==meta['source_order'] and case['scene_binding_sha256']==meta['scene_binding_sha256'] and case['word_ABI_sha256']==meta['word_ABI_sha256'],'binding/order')
    need(case['reference_length_not_geometric_length'] is True,'Lgeom not Lref')
    for key in ('accepted_complete_geometry','accepted_full_field_pipeline','GLSL_compiled','GPU_executed','GPU_job_admission','phase_evaluated'):
        need(case[key] is False,'no promotion '+key)
    def words_from(raw):return list(struct.unpack('<'+'I'*(len(raw)//4),raw))
    tw=words_from(buffers['triangles']);need(len(tw)%35==0,'triangles')
    planes={}
    for start in range(0,len(tw),35):
        row=tw[start:start+35];owner=row[0];xs=[hilo(row[i:i+2]) for i in (1,7,13)]
        radius=integer(row[19:35]);need(radius>=0 and xs[0]==xs[1]==xs[2] and owner in (0,1),'shared X')
        plane={'center':xs[0],'radius':radius,'lo':xs[0]-radius,'hi':xs[0]+radius}
        need(owner not in planes or planes[owner]==plane,'shared owner')
        planes[owner]=plane
    need(set(planes)=={0,1},'both owners')
    for owner,plane in planes.items():need({k:integer(v) for k,v in case['planes'][str(owner)].items()}==plane,'plane words')
    sw=words_from(buffers['sources']);need(len(sw)==32*len(meta['source_order']) and len(case['sources'])==len(meta['source_order']),'source count')
    M,D=planes[0],planes[1]
    old={s['source_id']:s for s in oldgeo[name]['sources']}
    for i,actual in enumerate(case['sources']):
        row=sw[32*i:32*(i+1)];source=meta['source_order'][i];sources+=1
        need(actual['source_id']==source,'sourceID')
        s,dirx=hilo(row[:2]),hilo(row[6:8]);rad=integer(row[12:28])
        need(rad>=0 and abs(dirx)==2**149 and hilo(row[8:10])==hilo(row[10:12])==0,'axial')
        sigma=1 if dirx>0 else -1;lo,hi=s-rad,s+rad
        need(actual['direction_sign']==sigma and list(map(integer,actual['source_X_interval_words']))==[lo,hi],'source interval')
        first=[M['lo']-hi,M['hi']-lo]
        second=[M['lo']-D['hi'],M['hi']-D['lo']]
        length=[2*M['lo']-hi-D['hi'],2*M['hi']-lo-D['lo']]
        other=[D['lo']-hi,D['hi']-lo]
        if sigma<0:first,second,length,other=[[-v[1],-v[0]] for v in (first,second,length,other)]
        for key,expected in [('first_X_distance_words',first),('second_X_distance_words',second),('geometric_length_words',length),('initial_other_owner_X_distance_words',other)]:
            need(list(map(integer,actual[key]))==expected,'input-only interval '+key)
        positive=all(v[0]>0 for v in (first,second,length))
        clearance=first[0]>0 and (other[1]<0 or other[0]>first[1])
        need(actual['X_distances_strictly_positive_CPU_only']==positive,'positivity')
        need(actual['initial_plane_clearance_and_competition_CPU_only']==clearance,'clearance')
        need(actual['conservative_X_plane_profile_pass_CPU_only']==(positive and clearance),'plane profile')
        plane_pass+=int(positive and clearance)
        need(actual['accepted_complete_geometry'] is False and actual['YZ_competition_tree_implemented'] is False,'incomplete geometry')
        prior=old[source]
        if prior['accepted_geometry_words_CPU_only']:
            need(length==prior['length_interval_scaled'],'retained length')
            need(first==prior['segments'][0]['segment_interval_scaled'] and second==prior['segments'][1]['segment_interval_scaled'],'retained distances')
            matches+=1;matched_cases.add(name)
for name in ('source_contact_FAIL','thin_collapsed_FAIL','declared_contact_FAIL','otherowner_contact_FAIL'):
    need(current['cases'][name]['sources'][0]['conservative_X_plane_profile_pass_CPU_only'] is False,'retain contact FAIL')
need(oldgeo['boundary_FAIL']['accepted_geometry_words_CPU_only'] is False and current['cases']['boundary_FAIL']['sources'][0]['X_distances_strictly_positive_CPU_only'] is True,'YZ boundary counterexample')
need(sources==14 and matches==9 and len(matched_cases)==8,'actual retained counts')
shader=(ROOT/'Blender/benchmarks/capacity_audit/axial_native_signed512_v1.glsl').read_text()
need('umulExtended(ua.w[i],ub.w[j],hi,lo)' in shader and 'void main' not in shader and shader.count('{')==shader.count('}'),'header only static checks NOT compiler')
print(json.dumps({'PASS':True,'pins':len(r['code_doc_sha256']),'inherited_pins':len(r['inherited_pins']),'cases':13,'sources':sources,'retained_interval_matches':matches,'retained_available_cases':len(matched_cases),'conservative_plane_profile_pass_rows':plane_pass,'new_semantic_call_counts_NOT_hardware_costs':all_counts,'initial_shape_rejections_unverifiable_after_tuple_JSON_coercion':unverifiable_initial_shape_rejections,'GLSL_compiled':False,'GPU_executed':False,'accepted_complete_geometry':False},sort_keys=True))

